// The dependency inventory, and why it is generated by hand rather than by a plugin.
//
// GitLab's Dependency Scanning is not a Free-tier feature, so this file IS this project's record of
// what it ships. What is COMMITTED is `sbom/dependencies.txt`: one sorted package coordinate per
// line, so taking on a dependency is +1 line in review, next to the change that caused it. That is
// the only reason to commit anything here — a 935 KB CycloneDX document, which is what the first
// attempt produced, is a fine SBOM whose diff nobody reads.
//
// **The plugin was tried first and REMOVED, and the reason is worth keeping.** `org.cyclonedx.bom`
// 3.3.0 perturbed `:app`'s variant resolution: with it applied, `:app:kspFossDebugKotlin` asked for
// `:core:model`'s classes with `org.gradle.jvm.environment=standard-jvm` and
// `kotlin.platform.type=jvm` — JVM variants of an Android library — and failed with
// "File/directory does not exist: core/model/build/libs/model.jar". It passed on this machine and
// died on the first clean CI checkout, because locally that jar already existed from an earlier
// build of the pure-JVM modules. A green local run proved nothing about a clean tree, again.
//
// Resolving the classpath directly is also simply less machinery: `checkNoNetworkingDeps` in the
// root build file has walked these same configurations for months, and this reuses that approach.
val committedInventory = layout.projectDirectory.file("sbom/dependencies.txt").asFile
val inventoryBuilt = layout.buildDirectory.file("sbom/dependencies.txt")

val inventoryHeader = listOf(
    "# Generated — do not edit. Regenerate with `./gradlew :app:updateSbom` and commit.",
    "#",
    "# Every artifact on the release runtime classpath of BOTH shipping flavours, sorted and",
    "# deduplicated. This file exists to make a dependency change VISIBLE IN REVIEW.",
    "#",
    "# `local:` lines are modules of this repo — 'we added a module' and 'we took on a dependency'",
    "# are different events and should not look the same in a diff.",
)

// The two configurations that describe what actually ships. Release, not debug: a test-only or
// tooling artifact on a debug classpath is not something this file should imply is shipped.
val shippedConfigurations = listOf("fossReleaseRuntimeClasspath", "playReleaseRuntimeClasspath")

tasks.register("buildSbomInventory") {
    group = "verification"
    description = "Resolves both shipping flavours' release classpaths into a sorted inventory."
    // Same opt-out, and the same reason, as checkNoNetworkingDeps: resolving a configuration at
    // execution time is something the repo-wide configuration cache forbids.
    notCompatibleWithConfigurationCache("resolves dependency configurations at execution time")
    val out = inventoryBuilt
    val header = inventoryHeader
    val configNames = shippedConfigurations
    outputs.file(out)
    // Never up-to-date. This task's real input is the RESOLVED dependency graph, which Gradle
    // cannot express as a file input — so with only an output declared it was skipped whenever the
    // file existed, and the guardrail compared the committed inventory against a stale copy of
    // itself. Caught when excluding junit from the KeePassJava2 graph changed nothing in the
    // regenerated list. Resolving two configurations costs well under a second.
    outputs.upToDateWhen { false }
    doLast {
        val lines = sortedSetOf<String>()
        configNames.forEach { name ->
            val cfg = configurations.findByName(name)
                ?: throw GradleException("Inventory guardrail: no configuration named $name on :app.")
            cfg.incoming.artifactView { lenient(true) }.artifacts.forEach { artifact ->
                val id = artifact.id.componentIdentifier
                lines += when (id) {
                    is org.gradle.api.artifacts.component.ProjectComponentIdentifier ->
                        "local:${id.projectPath}"
                    // displayName is "group:name:version" for a module.
                    else -> id.displayName
                }
            }
        }
        if (lines.isEmpty()) {
            throw GradleException("Inventory guardrail resolved nothing — the scan is broken, not the graph.")
        }
        val file = out.get().asFile
        file.parentFile.mkdirs()
        file.writeText((header + "" + lines.toList()).joinToString("\n") + "\n")
    }
}

tasks.register<Copy>("updateSbom") {
    group = "verification"
    description = "Regenerates the committed dependency inventory. Run after any dependency change."
    // `from(tasks.named(...))` rather than the raw provider: a plain layout.buildDirectory provider
    // carries no producer link, so Copy would silently run with nothing to copy — which it did once,
    // and reported success.
    from(tasks.named("buildSbomInventory"))
    into(committedInventory.parentFile)
}

tasks.register("checkSbomUpToDate") {
    group = "verification"
    description = "Fails if the committed dependency inventory no longer matches the resolved graph."
    dependsOn("buildSbomInventory")
    val target = committedInventory
    val built = inventoryBuilt
    doLast {
        if (!target.isFile) {
            throw GradleException("Dependency-inventory guardrail: ${target.path} is missing. Run `./gradlew :app:updateSbom`.")
        }
        val fresh = built.get().asFile.readText()
        if (target.readText() != fresh) {
            val committed = target.readLines().filterNot { it.startsWith("#") || it.isBlank() }.toSet()
            val current = fresh.lines().filterNot { it.startsWith("#") || it.isBlank() }.toSet()
            val added = (current - committed).sorted()
            val removed = (committed - current).sorted()
            throw GradleException(
                "Dependency-inventory guardrail FAILED — the resolved dependency graph no longer " +
                    "matches ${target.name}.\n\n" +
                    (if (added.isNotEmpty()) "  arrived:\n" + added.joinToString("\n") { "    + $it" } + "\n" else "") +
                    (if (removed.isNotEmpty()) "  gone:\n" + removed.joinToString("\n") { "    - $it" } + "\n" else "") +
                    "\nRun `./gradlew :app:updateSbom` and commit the result. Read the list above " +
                    "first: a dependency that arrived without anyone choosing it is exactly what " +
                    "this check exists to surface.",
            )
        }
        println("Dependency-inventory guardrail OK: ${target.name} matches the resolved graph.")
    }
}

// Release signing material, and why it is read here rather than committed.
//
// Nothing about the signing key may live in the repo (.gitignore excludes *.keystore). CI supplies
// it as masked variables; a maintainer signing locally can pass the same four values as Gradle
// properties in ~/.gradle/gradle.properties, which is outside the working tree.
//
// All four must be present or none of them count. A partially-configured keystore silently falling
// back to debug signing is the failure this whole block exists to prevent, so "three of four" is
// treated as "none" and reported, not quietly ignored.
val signingEnv: (String, String) -> String? = { env, prop ->
    (providers.environmentVariable(env).orNull ?: providers.gradleProperty(prop).orNull)
        ?.takeIf { it.isNotBlank() }
}
val ksPath = signingEnv("LOCALKEEP_KEYSTORE", "localkeep.keystore")
val ksPassword = signingEnv("LOCALKEEP_KEYSTORE_PASSWORD", "localkeep.keystorePassword")
val ksAlias = signingEnv("LOCALKEEP_KEY_ALIAS", "localkeep.keyAlias")
val ksKeyPassword = signingEnv("LOCALKEEP_KEY_PASSWORD", "localkeep.keyPassword")
val signingParts = mapOf(
    "LOCALKEEP_KEYSTORE" to ksPath,
    "LOCALKEEP_KEYSTORE_PASSWORD" to ksPassword,
    "LOCALKEEP_KEY_ALIAS" to ksAlias,
    "LOCALKEEP_KEY_PASSWORD" to ksKeyPassword,
)
val hasCompleteSigningMaterial = signingParts.values.all { it != null }

// Deliberately NOT gated on `CI`. The pipeline runs `assembleFossRelease assemblePlayRelease` on
// every push as an R8/shrinker gate, not to produce an uploadable — failing there for a missing
// keystore would turn the whole pipeline red for no safety gain. Upload safety is enforced by the
// explicit `checkReleaseSigning` task below, which the release job must run.
if (!hasCompleteSigningMaterial && signingParts.values.any { it != null }) {
    val missing = signingParts.filterValues { it == null }.keys.sorted()
    error(
        "Release signing is partially configured — missing: ${missing.joinToString(", ")}. " +
            "Supply all four or none; a partial config would silently debug-sign.",
    )
}

if (!hasCompleteSigningMaterial) {
    logger.warn(
        "LocalKeep: no release keystore configured — `assembleRelease` output will be " +
            "DEBUG-SIGNED. Fine for local R8 checks; never upload it.",
    )
}

// The pre-upload gate. `assembleRelease` succeeding proves nothing about which key signed the
// result, which is precisely how a debug-signed APK reaches Play Console. Run this in the same
// invocation that produces an artifact for upload:
//
//     ./gradlew :app:checkReleaseSigning :app:assemblePlayRelease
//
// It is deliberately a configuration-state assertion rather than an apksigner call on the output:
// the thing that decides the signature is whether a real signingConfig existed at configuration
// time, and checking that needs no SDK build-tools lookup and cannot be fooled by a stale APK.
tasks.register("checkReleaseSigning") {
    group = "verification"
    description = "Fails unless a real release signing key is configured — run before any upload."
    val configured = hasCompleteSigningMaterial
    val names = signingParts.keys.sorted()
    doLast {
        if (!configured) {
            error(
                "Release signing key is NOT configured — a release built now is signed with the " +
                    "public Android debug key and must never be uploaded. Set all four of: " +
                    names.joinToString(", ") + " (env vars, or localkeep.* Gradle properties).",
            )
        }
        println("Release signing OK: a real keystore is configured.")
    }
}

/**
 * The one command that produces an uploadable, with the signing gate welded on.
 *
 * `checkReleaseSigning` only helps if someone remembers to run it, and the thing it guards against —
 * a debug-signed APK reaching Play Console — happens precisely when someone is in a hurry and types
 * `assemblePlayRelease` on its own. So the release step is a task rather than a documented pair, and
 * the gate is a `dependsOn` rather than a line in a runbook.
 *
 * `mustRunAfter` is deliberately absent and would be wrong: the check is a configuration-state
 * assertion, so it is cheapest and most useful *before* twenty minutes of R8. Gradle is free to run
 * it first, and a failure there stops the assembles from running at all.
 *
 * `bundlePlayRelease` is in the list because Play has not accepted an APK for a new app since
 * August 2021 — the Play half of an upload is the AAB, and an `assemblePlayRelease` APK cannot be
 * uploaded at all. Without it this task described itself as "the only command that should produce
 * an upload" while producing nothing uploadable, which is the same class of gap `checkReleaseSigning`
 * exists to close. `assemblePlayRelease` stays: the APK is what gets installed on a device to verify
 * the minified build before the bundle goes anywhere.
 */
tasks.register("releaseArtifacts") {
    group = "publishing"
    description = "Signing-gated release build — the only command that should produce an upload."
    dependsOn(
        "checkReleaseSigning",
        "assembleFossRelease",
        "assemblePlayRelease",
        "bundlePlayRelease",
    )
}

android {
    namespace = "com.localkeep.app"
    compileSdk = libs.versions.compileSdk.get().toInt()

    defaultConfig {
        applicationId = "com.localkeep"
        minSdk = libs.versions.minSdk.get().toInt()
        targetSdk = libs.versions.targetSdk.get().toInt()
        versionCode = 2
        versionName = "1.0.1"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    signingConfigs {
        // Created only when all four values are present — see hasCompleteSigningMaterial above.
        // When absent, `release` simply does not exist and buildTypes falls back to debug with a
        // loud warning, which is fine locally and impossible on CI.
        if (hasCompleteSigningMaterial) {
            create("release") {
                storeFile = file(ksPath!!)
                storePassword = ksPassword
                keyAlias = ksAlias
                keyPassword = ksKeyPassword
            }
        }
    }

    flavorDimensions += "distribution"
    productFlavors {
        create("play") {
            dimension = "distribution"
            buildConfigField("boolean", "IS_FOSS", "false")
        }
        create("foss") {
            dimension = "distribution"
            applicationIdSuffix = ".foss"
            buildConfigField("boolean", "IS_FOSS", "true")
        }
    }

    lint {
        // The whole point: :app's lint run walks its library dependencies, so one
        // invocation covers all 18 string-bearing modules instead of 18 invocations.
        checkDependencies = true
        abortOnError = true
        warningsAsErrors = false
        lintConfig = rootProject.file("lint.xml")
        // Written where CI can pick it up; the text report is what a human reads.
        textReport = true
        htmlReport = true
    }

    buildTypes {
        debug {
            // en-XA accents every character and pads strings ~40% longer; en-XB
            // reverses text direction. Both are generated by AGP at build time
            // from values/strings.xml, so they exist the moment a string is
            // extracted and BEFORE any translator is involved.
            //
            // This is what makes the i18n plan's ordering work: an unaccented
            // word on an en-XA screen is a string we failed to extract, and a
            // clipped one is a layout that cannot take German. Both get found
            // once, in English, instead of four times.
            isPseudoLocalesEnabled = true
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            isDebuggable = false
            // No release keystore is committed (P1 .gitignore excludes *.keystore; the real
            // upload key lives in CI/env secrets). Debug-signing here is ONLY so
            // `assembleRelease` is independently buildable/installable for local R8
            // verification; production releases must supply a real signingConfig.
            //
            // This used to be an unconditional `signingConfigs.getByName("debug")`, and that is
            // exactly how a debug-signed release APK ends up in `build/outputs` looking
            // indistinguishable from an uploadable one. The debug key's private half ships inside
            // every Android SDK on earth, so uploading it would pin a public keypair as the app's
            // upload identity — recoverable only by a formal Google key-reset request. The
            // fallback stays, because local R8 verification needs it, but it is now (a) explicit,
            // (b) impossible to reach on CI, and (c) checked before upload by `checkReleaseSigning`.
            signingConfig = signingConfigs.findByName("release") ?: signingConfigs.getByName("debug")
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
        }
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    // DrawerOwnsBackOverNavHostTest composes the real shell around a real NavHost under
    // Robolectric, so it needs this module's merged manifest and resources on the unit-test
    // classpath. Same switch the feature modules already set for their Compose unit tests.
    testOptions {
        unitTests {
            isIncludeAndroidResources = true
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

kotlin {
    compilerOptions {
        jvmTarget = JvmTarget.JVM_17
    }
}

