// TierGClaimsTest opens every module's `values*/strings.xml` by path, which Gradle cannot infer
// from the classpath — so it has to be told, or the task is UP-TO-DATE through exactly the edit it
// exists to catch. That is measured, not assumed: an earlier draft of the test lived in
// :feature:vaultlist and a mutated German string re-ran nothing at all.
tasks.withType<Test>().configureEach {
    inputs.files(
        rootProject.fileTree(rootProject.projectDir) {
            include("**/src/main/res/values*/strings.xml")
            exclude("**/build/**")
        },
    ).withPropertyName("tierGStrings").withPathSensitivity(PathSensitivity.RELATIVE)
    // ComposedPluralAgreementTest walks the Kotlin sources looking for a plural being fed into a
    // format string — a defect class lint cannot see, so the set of call sites has to be pinned.
    inputs.files(
        rootProject.fileTree(rootProject.projectDir) {
            include("**/src/main/kotlin/**/*.kt")
            exclude("**/build/**")
        },
    ).withPropertyName("composedPluralSources").withPathSensitivity(PathSensitivity.RELATIVE)
    // KdfMemoryDocsMatchCodeTest compares the published Argon2id memory figure against
    // KdfParams.PORTABLE_MAX_MEMORY_KIB. Both sides are read by path, so both have to be declared:
    // without them a docs-only edit leaves the task UP-TO-DATE and the guard never runs. Measured
    // while writing it — reinstating `64 MiB` in FEATURES.md re-ran nothing.
    // AppShortcutsTest compares res/xml/shortcuts.xml's target package against the application ids
    // in this file and in the foss source set's strings.xml. All three are read by path, and the
    // `tierGStrings` tree above covers src/main/res only, so without these a flavour-id change
    // leaves the task UP-TO-DATE through exactly the edit the guard exists to catch.
    inputs.files(
        rootProject.files(
            "app/build.gradle.kts",
            "app/src/main/res/xml/shortcuts.xml",
            "app/src/foss/res/values/strings.xml",
        ),
    ).withPropertyName("shortcutTargets").withPathSensitivity(PathSensitivity.RELATIVE)
    inputs.files(
        rootProject.files(
            "FEATURES.md",
            "COMPARISON.md",
            "docs/THREAT-MODEL.md",
            "core/crypto/src/main/kotlin/com/localkeep/core/crypto/KdfParams.kt",
        ),
    ).withPropertyName("kdfMemoryDocs").withPathSensitivity(PathSensitivity.RELATIVE)
}

